#include <stdio.h>

/* 结构体定义：把「一个点」需要的两个坐标打包成一种新类型 */
struct Point {
    int x;
    int y;
};   /* 这个分号最容易漏，漏了编译器会报一串看不懂的错 */

int main() {
    struct Point p;
    /* p.x 本身就是一个普通的 int 变量，所以 scanf 同样要加 & */
    scanf("%d %d", &p.x, &p.y);

    printf("%d\n", p.x + p.y);
    printf("%d\n", p.x * p.y);
    return 0;
}

