#include <stdio.h>

struct Student {
    char name[20];   /* 存 19 个字符就要留一个位置给结尾的 '\0' */
    int score;
};

int main() {
    int n;
    scanf("%d", &n);

    struct Student list[100];
    int sum = 0;
    for (int i = 0; i < n; i++) {
        /* name 是数组名，本身就是地址；score 是 int，所以要加 & */
        scanf("%s %d", list[i].name, &list[i].score);
        sum += list[i].score;
    }

    /* sum 和 n 都是整数，写成 sum / n 会做整数除法把小数丢掉，
       所以分母要转成 double */
    printf("%.2f\n", sum / (double)n);

    /* 打擂台：记住的是下标，因为最后要输出的是姓名而不是分数 */
    int best = 0;
    for (int i = 1; i < n; i++) {
        if (list[i].score > list[best].score) {
            best = i;
        }
    }
    printf("%s\n", list[best].name);
    return 0;
}

