#include <stdio.h>

struct Student {
    int id;
    int score;
};

/* 返回结构体：把成员组装好，整体交出去 */
struct Student make_student(int id, int score) {
    struct Student s;
    s.id = id;
    s.score = score;
    return s;   /* 返回的是这份数据的拷贝，可以放心用 */
}

/* 参数是指针：函数里改的就是调用者那个结构体本身 */
void add_bonus(struct Student *s, int bonus) {
    s->score += bonus;   /* s->score 就是 (*s).score */
}

int main() {
    int id, score, bonus;
    scanf("%d %d %d", &id, &score, &bonus);

    struct Student stu = make_student(id, score);

    /* 必须传 &stu：按值传参改不到原件，只有地址才行 */
    add_bonus(&stu, bonus);

    printf("%d\n", stu.id);
    printf("%d\n", stu.score);
    return 0;
}

tutorial.code:
/* 这样写改不到调用者的变量 */
void add_bonus(struct Student s, int bonus) {
    s.score += bonus;   /* 只改了副本 */
}

/* 正确写法：传地址 */
void add_bonus(struct Student *s, int bonus) {
    s->score += bonus;
}

struct Student s;
struct Student *p = &s;
s.score = 90;
p->score = 95;              /* 改的是同一个 s */
printf("%d %d\n", s.score, (*p).score);

