#include <stdio.h>

/* typedef 给这个结构体起别名 Student，以后不用再写 struct 关键字 */
typedef struct {
    char name[20];
    int score;
} Student;

int main() {
    int n;
    scanf("%d", &n);

    Student list[100];
    for (int i = 0; i < n; i++) {
        scanf("%s %d", list[i].name, &list[i].score);
    }

    /* 冒泡排序，从高到低。
       条件写严格小于：分数相同时不交换，输入顺序自然保留下来 */
    for (int i = 0; i < n - 1; i++) {
        for (int j = 0; j < n - 1 - i; j++) {
            if (list[j].score < list[j + 1].score) {
                /* 交换的是整个学生，姓名和成绩必须一起搬家 */
                Student tmp = list[j];
                list[j] = list[j + 1];
                list[j + 1] = tmp;
            }
        }
    }

    for (int i = 0; i < n; i++) {
        printf("%s\n", list[i].name);
    }
    return 0;
}

