#include <stdio.h>

/* 共用体：三个成员共用同一块内存，大小取最大的那个成员 */
union Data {
    int i;
    float f;
    char c[4];
};

int main() {
    int n;
    scanf("%d", &n);

    union Data u;
    /* 三个成员都是 4 字节，所以整个共用体只占 4 字节 */
    printf("sizeof(union Data) = %d\n", (int)sizeof(u));

    u.i = n;
    /* 只写过 u.i，但 u.f 和它共用同一块内存：
       这里读到的是同一批二进制位被当成 float 解释的结果，不是数值转换 */
    printf("u.f = %.2f\n", u.f);
    return 0;
}

